function enterPipelineStage(index, options = {}) {
  const retainedMolecularCoverFocus = Number(index) === 0 ? "all" : molecularCoverFocus;
  pipelineStage = Math.max(0, Math.min(4, index));
  stageElapsed = 0;
  setPlaying(false);
  resetCounters();
  molecularCoverFocus = retainedMolecularCoverFocus;
  if (scenarioSelect.value === "imported") syncImportedFrameMaterial();
  rngState = 0x8f23ab17 ^ scenarioSelect.selectedIndex * 0x91e10da5
    ^ confinementSelect.selectedIndex * 0x734a9d ^ growthDomainScale * 0x45d9f3b;
  referenceAtoms = makeReferenceConfiguration();
  bindExternalForceGeometryToReference(referenceAtoms);
  referenceSpacing = scenarioSelect.value === "imported" ? .92 : medianNearestSpacing(referenceAtoms);
  referenceSpacingA = scenarioSelect.value === "imported"
    ? currentImportedFrameValidation().medianNearestDistance
    : referenceSpacing / .92 * currentMaterial().spacingA;
  ensemblePairDistanceUncertainty = learnReferenceEnsemblePairUncertainty();
  coloredDistanceEnvelopes = learnReferenceDistanceEnvelopes(referenceAtoms);
  fittedContactEnvelope = fitAdditiveContactEnvelope(coloredDistanceEnvelopes, {
    priorRadiiAngstrom: EXPLICIT_COVALENT_RADII_A,
    sceneToAngstrom: referenceSpacingA / Math.max(1e-12, referenceSpacing),
  });
  coloredCoordinationEnvelopes = learnReferenceCoordinationEnvelopes(referenceAtoms);
  coloredAngularEnvelopes = learnReferenceAngularEnvelopes(referenceAtoms);
  compositionTarget = learnCompositionTarget(referenceAtoms.map((atom) => atom.species));
  feedstockReservoir = initializeFeedstockReservoir(referenceAtoms.map((atom) => atom.species), feedstockSupplyMode);
  const chargeObservations = new Map();
  referenceAtoms.forEach((atom) => {
    const key = String(atom.species);
    const charge = Number.isFinite(atom.formalCharge) ? atom.formalCharge : formalChargeFromChemistryToken(key);
    const values = chargeObservations.get(key) || [];
    values.push(charge); chargeObservations.set(key, values);
  });
  suppliedFormalChargeBySpecies = new Map([...chargeObservations.entries()]
    .filter(([, values]) => values.length && values.every((value) => Number.isFinite(value)
      && Math.abs(value - values[0]) <= 1e-10))
    .map(([species, values]) => [species, values[0]]));
  formalChargeTarget = learnFormalChargeTarget(referenceAtoms.map((atom) => atom.species), suppliedFormalChargeForToken);
  referenceStructuralStats = calculateStructuralStats(referenceAtoms, referenceSpacing, currentPbc().some(Boolean),
    currentMaterial().intrinsicDimension === 2 ? 2 : 3);
  learnedClusters = learnLocalEnvironmentClusters(referenceAtoms);
  learnedCover = buildExhaustiveClusterCover(referenceAtoms);
  detectedUnitCell = geometryMode === "module" || geometryMode === "offlattice" ? null : inferTranslationCell(referenceAtoms);
  trainedMarking = learnOverlapMarking(referenceAtoms);
  overlapGrammar = learnOverlapGrammar(referenceAtoms);
  orientationAtlas = learnOrientationAtlas();
  microstructureEvidence = learnMicrostructureEvidence();
  clusterDiscoveryTrace = buildClusterDiscoveryTrace();
  clusterDiscoveryProgress = pipelineStage === 1
    ? Math.min(1, clusterDiscoveryTrace.totalSteps) : clusterDiscoveryTrace.totalSteps;
  if (pipelineStage === 1) eventIndex = clusterDiscoveryProgress;
  const currentVocabularyKey = markingVocabularyKey();
  const compatibleActive = markingLibrary.find((marking) => marking.id === activeMarkingId
    && marking.materialKey === markingMaterialKey()
    && marking.vocabularyKey === currentVocabularyKey
    && marking.coefficients.length === markingPrototypeTypes().length
    && markingMatchesDraft(marking));
  const growthMarking = compatibleActive || (pipelineStage === 4
    ? compatibleMarkings().filter(markingMatchesDraft).at(-1) : null);
  if (pipelineStage === 4 && growthMarking) {
    activeMarkingId = growthMarking.id;
    markingDraft = { ...growthMarking.config,
      channels: growthMarking.config.channelMode === "auto" ? 0 : growthMarking.config.channels };
  }
  sectionModel = learnSectionModel(referenceAtoms, currentMarkingConfig());
  if (pipelineStage === 3) scheduleMarkingCapacityFrontier(referenceAtoms);
  else {
    markingCapacityAuditToken++;
    markingCapacityFrontierAudit = null;
    markingCapacityAuditProgress = null;
  }
  if (pipelineStage !== 3) trainingProgress = markingSampleCount();
  if (pipelineStage === 4) {
    const compatible = compatibleMarkings();
    if (!compatible.length) freezeCurrentMarking();
  }
  if (pipelineStage >= 3 && policySelect.value === "marked") seedTrainedMarking();
  if (pipelineStage === 0 || pipelineStage === 1) atoms = referenceAtoms.map((atom) => cloneAtom(atom));
  else if (pipelineStage === 2) atoms = makeRepresentatives().map((atom) => cloneAtom(atom));
  else if (pipelineStage === 3) atoms = makeRepresentatives().map((atom) => cloneAtom(atom));
  else if (currentMaterial().growthWithheld) atoms = referenceAtoms.map((atom) => cloneAtom(atom));
  else if (learnedCover.molecular?.water
    && (currentMaterial().icePolytype || scenarioSelect.value === "iceVI")) initializeIceAnchorSearch();
  else if (scenarioSelect.value === "iqc" && growthSeedProtocol === "sealed-iqc-confirmation") {
    initializeIqcDisjointConfirmationSearch();
  }
  else initializeOffLatticeSearch();
  if (pipelineStage < 4) rebuildSpatialIndex();
  buildConfinement();
  clusterGroup.rotation.set(0, 0, 0);
  clusterGallery.hidden = pipelineStage !== 3;
  viewport.classList.toggle("cluster-gallery-mode", pipelineStage === 3);
  viewportHint.textContent = pipelineStage === 3
    ? "one evolving marking scene per cluster · scroll for all types"
    : pipelineStage === 1 ? "full configuration · tentative → rejected → settled supports"
      : "drag to orbit · wheel to zoom · click an atom";
  if (pipelineStage === 3) rebuildClusterGallery();
  buildClusterOverlay();
  updateStageNarrative();
  rebuildWorld();
  updateUI();
  updatePipelineButtons();
  syncStageOptions();
  renderEnsembleControls();
  renderIceViMicrostateControls();
  frameStage();
  if (options.play) setPlaying(true);
}

function synchronizeWorkflowAddress({ mode = "push", clearStudy = false } = {}) {
  const url = new URL(window.location.href);
  const material = scenarioSelect.value;
  const shareableImportedSpecimen = material === "imported" && url.searchParams.has("specimen");
  if (material !== "imported" || shareableImportedSpecimen) url.searchParams.set("material", material);
  else url.searchParams.delete("material");
  url.searchParams.set("stage", String(pipelineStage));
  if (material === "iqc" && growthSeedProtocol === "sealed-iqc-confirmation") {
    url.searchParams.set("seedProtocol", growthSeedProtocol);
  } else url.searchParams.delete("seedProtocol");
  if (material !== "iceVI") url.searchParams.delete("microstate");
  else if (iceViMicrostate) url.searchParams.set("microstate", String(iceViMicrostate.audit.seed));
  if (material !== "imported") url.searchParams.delete("specimen");
  if (clearStudy) {
    url.searchParams.delete("study");
    url.searchParams.delete("studyVersion");
  }
  if (url.href === window.location.href) return false;
  const method = mode === "replace" ? "replaceState" : "pushState";
  window.history[method]({ gctsWorkflow: true, material, stage: pipelineStage }, "", url);
  return true;
}

function launchMaterialsWorkflowRoute({ scenario, stage, preparation = null } = {}) {
  const stageButton = document.querySelector(`[data-pipeline-stage="${stage}"]`);
  if (!scenarioSelect.querySelector(`option[value="${scenario}"]`) || !stageButton) return false;
  selectedStudyRecipeId = null;
  activeStudyRecipeId = null;
  if (scenarioSelect.value !== scenario) {
    scenarioSelect.value = scenario;
    scenarioSelect.dispatchEvent(new Event("change", { bubbles: true }));
  }
  if (preparation === "resolve-ice-vi" && !iceViAverageButton.hidden) iceViAverageButton.click();
  if (preparation === "resolve-ice-vi") iceViMicrostateButton.click();
  enterPipelineStage(Number(stage));
  synchronizeWorkflowAddress({ mode: "push", clearStudy: true });
  stageButton.scrollIntoView({ behavior: "smooth", block: "nearest" });
  return true;
}

function restoreWorkflowRouteFromAddress() {
  const parameters = new URLSearchParams(window.location.search);
  if (parameters.has("study") || parameters.has("experiment")
    || (parameters.has("specimen") && scenarioSelect.value !== "imported")) {
    window.location.reload();
    return;
  }
  const material = parameters.get("material");
  if (material && scenarioSelect.value !== material
      && scenarioSelect.querySelector(`option[value="${material}"]`)) {
    selectedStudyRecipeId = null;
    activeStudyRecipeId = null;
    scenarioSelect.value = material;
    scenarioSelect.dispatchEvent(new Event("change", { bubbles: true }));
  }
  if (scenarioSelect.value === "iceVI" && parameters.has("microstate")) {
    const requested = Number.parseInt(parameters.get("microstate"), 10);
    const seed = Number.isInteger(requested) && requested > 0 ? requested : 1;
    if (iceViMicrostate?.audit.seed !== seed) {
      iceViMicrostateSeed = seed;
      iceViMicrostate = resolveIceViIceRuleMicrostate(seed);
      renderIceViMicrostateControls();
    }
  }
  growthSeedProtocol = scenarioSelect.value === "iqc"
    && parameters.get("seedProtocol") === "sealed-iqc-confirmation"
    ? "sealed-iqc-confirmation" : recommendedGrowthSeedProtocol();
  const requestedStage = Number.parseInt(parameters.get("stage"), 10);
  enterPipelineStage(Number.isInteger(requestedStage) ? Math.max(0, Math.min(4, requestedStage)) : 0);
}

window.gctsMaterialsWorkflow = Object.freeze({ launch: launchMaterialsWorkflowRoute });
window.addEventListener("popstate", restoreWorkflowRouteFromAddress);

function updatePipelineButtons() {
  pipelineSteps.forEach((button) => {
    const stage = Number(button.dataset.pipelineStage);
    button.classList.toggle("active", stage === pipelineStage);
    button.classList.toggle("complete", stage < pipelineStage);
    button.setAttribute("aria-current", stage === pipelineStage ? "step" : "false");
    button.disabled = growthFrontierWork.busy;
  });
  pipelineButton.disabled = growthFrontierWork.busy;
  pipelineButton.classList.toggle("running", pipelineAuto);
  pipelineButton.textContent = pipelineAuto ? "Stop full pipeline" : "Run full pipeline";
}

function frameStage() {
  const large = pipelineStage === 4;
  const prototypes = pipelineStage === 2 || pipelineStage === 3;
  const target = new THREE.Vector3();
  controls.target.copy(target);
  camera.position.set(large ? 18 : prototypes ? 8 : 12.5, large ? 13 : prototypes ? 5.8 : 9.5, large ? 19 : prototypes ? 9 : 13.5);
  camera.updateProjectionMatrix();
}

